import {useQuery} from '@tanstack/react-query';import {api} from '../services/api';import {Card,Badge} from '../components/ui';import {Banknote,ClipboardList,Armchair,ChefHat,ArrowUpRight,Boxes} from 'lucide-react';import {AreaChart,Area,ResponsiveContainer,XAxis,YAxis,Tooltip,CartesianGrid} from 'recharts';import {Link} from 'react-router-dom';
const money=(n:number)=>`Rs ${Math.round(n||0).toLocaleString()}`;
export default function Dashboard(){const {data,isLoading}=useQuery({queryKey:['dashboard'],queryFn:()=>api.get('/dashboard').then(r=>r.data.data),refetchInterval:30000});const stats=[['Today’s sales',money(data?.todaySales),Banknote,'bg-emerald-50 text-emerald-600'],['Total orders',data?.totalOrders||0,ClipboardList,'bg-sky-50 text-sky-600'],['Active tables',data?.activeTables||0,Armchair,'bg-violet-50 text-violet-600'],['Kitchen queue',data?.pendingKitchen||0,ChefHat,'bg-amber-50 text-amber-600']];return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm font-semibold text-brand-600">GOOD AFTERNOON</p><h2 className="mt-1 text-2xl font-bold">Here’s how the restaurant is moving.</h2></div><div className="flex gap-2"><Link to="/menu" className="rounded-xl border bg-white px-4 py-2.5 text-sm font-semibold">Add menu item</Link><Link to="/pos" className="rounded-xl bg-brand-600 px-4 py-2.5 text-sm font-semibold text-white">Open POS</Link></div></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map(([label,value,Icon,color]:any)=><Card key={label} className="p-5"><div className="flex items-start justify-between"><span className={`grid h-11 w-11 place-items-center rounded-xl ${color}`}><Icon size={21}/></span><span className="flex items-center text-xs font-semibold text-emerald-600">8.4% <ArrowUpRight size={14}/></span></div><div className="mt-5 text-2xl font-bold">{isLoading?'—':value}</div><div className="mt-1 text-sm text-slate-500">{label}</div></Card>)}</div><div className="grid gap-6 xl:grid-cols-[1.6fr_1fr]"><Card className="p-5"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-bold">Revenue trend</h3><p className="text-sm text-slate-500">Last 14 days</p></div><select className="rounded-xl border px-3 py-2 text-sm"><option>Daily</option><option>Weekly</option></select></div><div className="h-72"><ResponsiveContainer><AreaChart data={data?.revenueChart||[]}><defs><linearGradient id="revenue" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#16a878" stopOpacity={.3}/><stop offset="95%" stopColor="#16a878" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0"/><XAxis dataKey="_id" tick={{fontSize:11}} axisLine={false}/><YAxis tick={{fontSize:11}} axisLine={false} tickFormatter={v=>`${v/1000}k`}/><Tooltip formatter={(v:any)=>money(v)}/><Area type="monotone" dataKey="revenue" stroke="#16a878" strokeWidth={3} fill="url(#revenue)"/></AreaChart></ResponsiveContainer></div></Card><Card className="overflow-hidden"><div className="flex items-center justify-between border-b p-5"><div><h3 className="font-bold">Low stock</h3><p className="text-sm text-slate-500">Needs your attention</p></div><Boxes size={20} className="text-rose-500"/></div><div className="divide-y">{data?.lowStock?.map((x:any)=><div key={x._id} className="flex items-center justify-between p-4"><div><div className="text-sm font-semibold">{x.name}</div><div className="text-xs text-slate-500">Minimum {x.minimumStock} {x.unit}</div></div><Badge tone="low">{x.currentStock} {x.unit}</Badge></div>)}{!data?.lowStock?.length&&<p className="p-6 text-sm text-slate-500">All stock levels look healthy.</p>}</div></Card></div><Card className="overflow-hidden"><div className="flex items-center justify-between border-b p-5"><h3 className="font-bold">Recent orders</h3><Link className="text-sm font-semibold text-brand-600" to="/orders">View all</Link></div><div className="overflow-x-auto"><table><thead><tr><th>Order</th><th>Guest / table</th><th>Type</th><th>Status</th><th>Total</th></tr></thead><tbody>{data?.recentOrders?.map((o:any)=><tr key={o._id}><td className="font-semibold">{o.orderNumber}</td><td>{o.table?.name||o.customer?.name||'Walk-in'}</td><td className="capitalize">{o.type}</td><td><Badge>{o.status}</Badge></td><td className="font-semibold">{money(o.total)}</td></tr>)}</tbody></table></div></Card></div>}
